mapper.select:
SELECT COUNT(*)
FROM GRP G
WHERE G.ID = #{grpId}
  AND G.PRJ_ID = #{prjId}
  AND G.STATUS_CD = '01ACTIVE'

SELECT COUNT(*)
FROM MEMBER M
WHERE M.USER_ID = #{userId}
  AND M.GRP_ID = #{grpId}

mapper.insert:
BEGIN

    INSERT INTO MEMBER (
      ID,
      USER_ID,
      GRP_ID
    ) VALUES (
      mem_seq.NEXTVAL,
      #{uid},
      #{grpId}
    )
  ;
END;

mapper.update:
UPDATE MEMBER M
SET M.GRP_ID = #{grpId}
WHERE M.USER_ID = #{userId}
  AND M.GRP_ID = #{oldGrpId}
  AND EXISTS (
    SELECT 1
    FROM GRP G
    WHERE G.ID = M.GRP_ID
      AND G.PRJ_ID = #{prjId}
      AND G.STATUS_CD = '01ACTIVE'
  )

mapper.delete:
DELETE FROM MEMBER M
WHERE EXISTS (
  SELECT 1 FROM GRP G WHERE G.ID = M.GRP_ID AND G.PRJ_ID = #{prjId}
)
AND (

    (M.USER_ID = #{r.userId} AND M.GRP_ID = #{r.grpId})

)

mapper.select:
